function lanceDashFx(p,range){const board=$('board'),fx=document.createElement('div');fx.className='lance-dash-fx';fx.innerHTML='<span class="lance-rider">🐎</span><span class="lance-spear">➤</span><span class="lance-trail">✦✦✦</span>';fx.style.left=`${(p.c+.25)*CELL_W}%`;fx.style.top=`${(p.r+.5)*CELL_H}%`;fx.style.setProperty('--dash',`${Math.min(range,3.2)*CELL_W}%`);board.appendChild(fx);for(let i=0;i<6;i++){const spark=document.createElement('div');spark.className='lance-spark';spark.textContent=i%2?'槍':'✦';spark.style.left=`${(p.c+.75+i*.38)*CELL_W}%`;spark.style.top=`${(p.r+.5+(i%2?-.12:.12))*CELL_H}%`;spark.style.animationDelay=`${i*35}ms`;board.appendChild(spark);setTimeout(()=>spark.remove(),760)}setTimeout(()=>fx.remove(),760)}
function heroSkillFx(cls,html,left,top,ms=900){const fx=document.createElement('div');fx.className=cls;fx.innerHTML=html;fx.style.left=left;fx.style.top=top;$('board').appendChild(fx);setTimeout(()=>fx.remove(),ms);return fx}
function guanyuDragonSlashFx(p,target){heroSkillFx('guanyu-dragon-fx','<span class="dragon-head">🐉</span><span class="dragon-flame">🔥🔥🔥</span><span class="dragon-blade">青龍斬</span>',`${(p.c+.75)*CELL_W}%`,`${(p.r+.48)*CELL_H}%`,950);for(let i=0;i<4;i++){setTimeout(()=>attackFx(target,'fire'),i*90)}}
function zhangfeiRoarFx(p,target){heroSkillFx('zhangfei-roar-fx','<span class="roar-face">吼！</span><span class="roar-wave">震</span><span class="roar-crack">▱▰▱</span>',`${(p.c+.9)*CELL_W}%`,`${(p.r+.48)*CELL_H}%`,850);attackFx(target,'boom')}
function zhaoyunIceDragonFx(p,target){heroSkillFx('zhaoyun-ice-fx','<span class="ice-dragon">❄️龍</span><span class="ice-lance">➤</span><span class="ice-mist">❄︎❄︎❄︎</span>',`${(p.c+.72)*CELL_W}%`,`${(p.r+.5)*CELL_H}%`,900);attackFx(target,'ice')}
function huangzhongArrowRainFx(p,rows){const board=$('board'),icons=['➶','➷','➴','➵','✦','✧'];const volley=document.createElement('div');volley.className='huangzhong-volley-fx';volley.innerHTML='<span class="golden-bow">🏹</span><span class="volley-fan">✦✦✦</span>';volley.style.left=`${(p.c+.82)*CELL_W}%`;volley.style.top=`${(p.r+.48)*CELL_H}%`;board.appendChild(volley);setTimeout(()=>volley.remove(),980);rows.forEach((r,ri)=>{const sweep=document.createElement('div');sweep.className='huangzhong-lane-sweep';sweep.style.top=`${(r+.48)*CELL_H}%`;sweep.style.animationDelay=`${ri*65}ms`;board.appendChild(sweep);setTimeout(()=>sweep.remove(),1050);for(let i=0;i<10;i++){const fx=document.createElement('div');fx.className='huangzhong-arrow-fx';fx.textContent=icons[(i+ri)%icons.length];fx.style.left=`${(p.c+1+i*.58)*CELL_W}%`;fx.style.top=`${(r+.06+(i%3)*.12)*CELL_H}%`;fx.style.animationDelay=`${ri*58+i*24}ms`;fx.style.setProperty('--arrow-rot',`${36+(i%4)*7}deg`);board.appendChild(fx);setTimeout(()=>fx.remove(),1120)}})}
function summonFx(e){const board=$('board');const fx=document.createElement('div');fx.className='liubei-benevolence-fx';fx.innerHTML='<span class="benevolence-crown">👑</span><span class="benevolence-aura">仁德</span><span class="benevolence-flags">⚔️⚔️⚔️</span>';fx.style.left=`${(e.c+.75)*CELL_W}%`;fx.style.top=`${(e.r+.4)*CELL_H}%`;board.appendChild(fx);[-1,0,1].forEach((dr,i)=>{const r=e.r+dr;if(r<0||r>=ROWS)return;const sigil=document.createElement('div');sigil.className='liubei-summon-sigil';sigil.textContent=i===1?'召':'令';sigil.style.left=`${(e.c+1.25)*CELL_W}%`;sigil.style.top=`${(r+.5)*CELL_H}%`;sigil.style.animationDelay=`${i*90}ms`;board.appendChild(sigil);setTimeout(()=>sigil.remove(),1050)});setTimeout(()=>fx.remove(),1050)}
function summonInfantry(p,type,rows,offset){const d=PLANT_TYPES[type];rows.filter(r=>r>=0&&r<ROWS).forEach(r=>{const c=Math.min(7.2,p.c+offset);state.plants.push({id:crypto.randomUUID(),type,c,r,hp:d.hp,maxHp:d.hp,last:0,bornAt:state.time,summoned:true,elite:!!d.elite})})}
function summonMilitia(p){summonInfantry(p,'swordSoldier',[p.r],.7);flash(p,'鄉勇出陣');sfx('place');log('仁德劉備發動天賦「召喚將士」，召喚一名蜀軍鄉勇。')}
function summonEliteGuards(p){summonInfantry(p,'whiteFeatherGuard',[-1,0,1].map(dr=>p.r+dr),1.45);p.actionAssetUntil=state.time+900;p.actionAsset=PLANT_TYPES.liubei.actionAsset;summonFx(p);sfx('ultimate');log('仁德劉備發動機率技能「白毦號令」，召喚上、中、下三路白毦禁衛！')}
function globalStrikeFx(){const board=$('board'),g=document.createElement('div');g.className='global-strike kongming-starfield';g.innerHTML='<span class="taiji">☯</span><span class="formation-ring">八陣</span><span class="thunder-seal">⚡</span>';board.appendChild(g);setTimeout(()=>g.remove(),1250);for(let r=0;r<ROWS;r++){for(let i=0;i<5;i++){setTimeout(()=>{const s=document.createElement('div');s.className='sigil kongming-sigil';s.textContent=pick(['☰','☱','☲','☳','☴','☵','☶','☷','⚡']);s.style.left=`${rand(10,92)}%`;s.style.top=`${(r+.22+rand(0,46)/100)*CELL_H}%`;board.appendChild(s);setTimeout(()=>s.remove(),1250)},r*62+i*58)}}for(let i=0;i<9;i++){setTimeout(()=>{const beam=document.createElement('div');beam.className='kongming-lightning';beam.style.left=`${rand(8,92)}%`;beam.style.top=`${rand(8,88)}%`;beam.style.setProperty('--bolt-rot',`${rand(-18,18)}deg`);board.appendChild(beam);setTimeout(()=>beam.remove(),780)},i*72)}}
function levelLabel(n){return ['','一','二','三','四','五','六','七','八','九','十'][n]||n}
const LEVEL_THEME={day:{card:'level-day',art:'day-art'},night:{card:'level-night',art:'night-art'},siege:{card:'level-siege',art:'siege-art'},final:{card:'level-final',art:'final-art'}};
function levelArtStyle(lv){if(!lv.cardArt)return '';const grad=lv.theme==='day'?'linear-gradient(180deg,rgba(255,255,255,.06),rgba(0,0,0,.09))':lv.theme==='night'?'linear-gradient(180deg,rgba(7,17,39,.53),rgba(0,0,0,.09))':lv.theme==='siege'?'linear-gradient(180deg,rgba(0,0,0,.06),rgba(0,0,0,.33))':'linear-gradient(180deg,rgba(0,0,0,.03),rgba(0,0,0,.36))';return `style="background-image:${grad},url('${lv.cardArt}') !important;background-size:cover;background-position:center;background-repeat:no-repeat"`}
function levelCast(lv){const plants=UNIT_ORDER.plants.filter(k=>isUnlocked('plants',k,lv.level)&&!PLANT_TYPES[k].hidden).map(k=>PLANT_TYPES[k].name),zombies=UNIT_ORDER.zombies.filter(k=>isUnlocked('zombies',k,lv.level)&&!ZOMBIE_TYPES[k].hidden&&lv.zombieWeights.includes(k)).map(k=>ZOMBIE_TYPES[k].name);return `<div class="level-cast"><b>出場人物</b><span>守方：${plants.slice(-4).join('、')}</span><span>僵屍：${[...new Set(zombies)].slice(-4).join('、')}</span></div>`}
function buildLevelCards(){const wrap=$('levelGrid');if(!wrap)return;wrap.innerHTML='';Object.values(LEVELS).forEach(lv=>{const theme=LEVEL_THEME[lv.theme||'day']||LEVEL_THEME.day,completed=isCampaignLevelCompleted(currentFaction,lv.level),unlocked=isCampaignLevelUnlocked(currentFaction,lv.level);const card=document.createElement('article');card.className=`level-card campaign-card ${theme.card}${completed?' completed':unlocked?' current':' locked'}`;const action=completed?`重玩第${levelLabel(lv.level)}關`:unlocked?`開始第${levelLabel(lv.level)}關`:'🔒 尚未解鎖';card.innerHTML=`<div class="level-ribbon ${lv.theme==='day'?'':'red'}"><span>第${levelLabel(lv.level)}關</span><strong>${lv.shortName}</strong></div><div class="level-art ${theme.art}" ${levelArtStyle(lv)}></div><p>${lv.cardText}</p>${levelCast(lv)}<div class="level-meta">難度：${lv.difficulty}${completed?'｜✅ 已通關':unlocked?'｜目前可玩':'｜完成前一關後解鎖'}</div><button class="level-start" data-jump-level="${lv.level}" ${unlocked?'':'disabled'}>${action}</button>`;card.querySelector('button').onclick=()=>startLevel(currentFaction,lv.level);wrap.appendChild(card)})}
function levelPhase(){return selectedLevel<=2?'入門':selectedLevel<=4?'普通':selectedLevel<=6?'進階':selectedLevel<=8?'將軍':'決戰'}
function levelIntroText(){const lv=LEVELS[selectedLevel];return `${lv.name}：${lv.cardText}`}
function levelPlantSummary(){const lv=LEVELS[selectedLevel];return `${lv.shortName}｜${levelPhase()}｜守方起始 ${lv.plantStart} 軍糧`}
function levelZombieSummary(){const lv=LEVELS[selectedLevel];return `${lv.shortName}｜${levelPhase()}｜僵屍起始 ${lv.zombieStart} 腦`}
function levelPlantDesc(){return LEVELS[selectedLevel].plantHint}
function levelZombieDesc(){return LEVELS[selectedLevel].zombieHint}
function refreshStartCopy(){const lv=LEVELS[selectedLevel];$('levelIntro').textContent=levelIntroText();$('plantSummary').textContent=levelPlantSummary();$('zombieSummary').textContent=levelZombieSummary();$('plantDesc').textContent=levelPlantDesc();$('zombieDesc').textContent=levelZombieDesc();$('plantStartBtn').textContent='選三國守方';$('zombieStartBtn').textContent='選僵屍陣營'}
function syncAppHistory(screen,mode='push'){if(history.state?.sgzScreen===screen)return;history[mode==='replace'?'replaceState':'pushState']({...history.state,sgzScreen:screen},'',location.href)}
function chooseFaction(faction){if(!isCampaignFactionUnlocked(faction)){refreshCampaignUI();return}playSceneMusic('stageSelect');sfx('click');currentFaction=faction;const progress=campaignSideProgress(faction);$('chosenFactionText').textContent=`已選陣營：${faction==='plants'?'三國守方':'僵屍方'}。已通關 ${progress.highestLevel}/10；已通關關卡可自由重玩。`;$('start').classList.remove('active');$('accountScreen')?.classList.remove('active');$('levelScreen').classList.add('active');buildLevelCards();syncAppHistory('level')}
function startLevel(faction,level){if(!isCampaignLevelUnlocked(faction,level))return;selectedLevel=level;start(faction)}
function clearBattleSave(){localStorage.removeItem(BATTLE_SAVE_KEY);refreshResumeBattleUI()}
function refreshResumeBattleUI(){const available=!!localStorage.getItem(BATTLE_SAVE_KEY);['resumeBattleCard','resumeBattleBtn','resumeBattleLevelBtn'].forEach(id=>$(id)?.classList.toggle('hidden',!available));return available}
function persistBattleState(){if(!state||state.over||!$('game')?.classList.contains('active'))return false;try{const savedState={...state,levelConfig:undefined,selected:null,actionMode:null,movingPlantId:null};localStorage.setItem(BATTLE_SAVE_KEY,JSON.stringify({version:BATTLE_SAVE_VERSION,savedAt:Date.now(),cloudMatchId,state:savedState}));refreshResumeBattleUI();return true}catch(e){return false}}
function applyPausedBattleUI(){if(!state)return;$('game').classList.toggle('paused',state.paused);$('pauseOverlay')?.classList.toggle('show',state.paused);if($('pauseBtn'))$('pauseBtn').textContent=state.paused?'繼續':'暫停'}
function pauseAndSaveBattle(reason='background'){if(!state||state.over||!$('game')?.classList.contains('active'))return false;const newlyPaused=!state.paused;state.paused=true;state.actionMode=null;state.movingPlantId=null;applyPausedBattleUI();updateBattleActionUI();persistBattleState();if(newlyPaused&&reason==='background')log('已自動暫停並保留目前戰局；回到遊戲後請按「繼續」。');return true}
function restoreBattleIfAvailable(){let snapshot;try{snapshot=JSON.parse(localStorage.getItem(BATTLE_SAVE_KEY)||'null')}catch(e){clearBattleSave();return false}const saved=snapshot?.state;if(snapshot?.version!==BATTLE_SAVE_VERSION||!saved||saved.over||!LEVELS[saved.level]||!['plants','zombies'].includes(saved.faction)||!isCampaignLevelUnlocked(saved.faction,saved.level)){clearBattleSave();return false}clearInterval(timer);syncAppHistory('battle');selectedLevel=saved.level;currentFaction=saved.faction;applyActiveSkins(saved.faction);cloudMatchId=snapshot.cloudMatchId||null;state={...saved,levelConfig:LEVELS[saved.level],enemiesSpawned:Number.isFinite(saved.enemiesSpawned)?saved.enemiesSpawned:Math.min(LEVELS[saved.level].enemyCount,Math.max(saved.zombies?.length||0,Math.floor(Math.max(0,(saved.time||0)-LEVELS[saved.level].firstZombieDelay)/Math.max(4000,LEVELS[saved.level].openingSpacing||6500)))),plants:Array.isArray(saved.plants)?saved.plants:[],zombies:Array.isArray(saved.zombies)?saved.zombies:[],projectiles:Array.isArray(saved.projectiles)?saved.projectiles:[],lawnmowers:Array.isArray(saved.lawnmowers)?saved.lawnmowers:[],lastHuman:saved.lastHuman||{},lastAI:saved.lastAI||{},usedUnits:saved.usedUnits||{plants:{},zombies:{}},paused:true,selected:null,actionMode:null,movingPlantId:null};if(state.bossSpawned&&state.nextAI===null)state.nextAI=Infinity;['start','accountScreen','levelScreen','characters','profile','shop'].forEach(id=>$(id)?.classList.remove('active'));$('game').classList.add('active');$('modal')?.classList.remove('show');$('log').innerHTML='';playSceneMusic('battle');buildGrid();$('board').classList.toggle('night',!!state.levelConfig.nightMode);$('game').classList.toggle('level-2-night',!!state.levelConfig.nightMode);buildCards();updateBattleActionUI();applyPausedBattleUI();updateHUD();render();timer=setInterval(tick,50);log('未完成戰局已還原並保持暫停，按「繼續」後才會推進。');return true}
function start(faction){
  if(!isCampaignLevelUnlocked(faction,selectedLevel)){backToHome();return false}
  applyActiveSkins(faction);
  clearBattleSave();clearInterval(timer);syncAppHistory('battle');playSceneMusic('battle');const lv=LEVELS[selectedLevel];
  const openingQueue=faction==='plants'?[...(lv.openingZombies||[])]:[];
  const firstZombieDelay=lv.firstZombieDelay||5000;
  const firstRegularWave=firstZombieDelay+(openingQueue.length?openingQueue.length*(lv.openingSpacing||3000)+1800:0);
  state={faction,level:selectedLevel,levelConfig:lv,resource:faction==='plants'?lv.plantStart:lv.zombieStart,aiResource:faction==='plants'?lv.plantAI:lv.zombieAI,selected:null,plants:[],zombies:[],projectiles:[],time:0,lastHuman:{},lastAI:{},over:false,paused:false,usedUnits:{plants:{},zombies:{}},actionMode:null,movingPlantId:null,enemiesSpawned:0,cloudMatchStartedAt:Date.now(),lawnmowers:Array.from({length:ROWS},(_,r)=>({r,used:false,x:.08,active:false})),openingQueue,nextOpeningZombie:firstZombieDelay,bossSpawned:false,nextAI:faction==='plants'?firstRegularWave:rand(3000,5600),nextIncome:3800};
  $('log').innerHTML='';$('start').classList.remove('active');$('levelScreen').classList.remove('active');$('game').classList.add('active');$('game').classList.toggle('level-2-night',!!lv.nightMode);$('modal').classList.remove('show');$('game').classList.remove('paused');if($('pauseOverlay'))$('pauseOverlay').classList.remove('show');if($('pauseBtn'))$('pauseBtn').textContent='暫停';buildGrid();$('board').classList.toggle('night',!!lv.nightMode);buildCards();updateBattleActionUI();seedLevel();updateHUD();render();timer=setInterval(tick,50);startCloudMatch(selectedLevel,faction);log(`${lv.name}｜${faction==='plants'?`三國守方開始；電腦僵屍將在 ${Math.round(firstZombieDelay/1000)} 秒後慢慢進場。`:'僵屍方開始。'}`)
}
function seedLevel(){if(state.faction==='zombies')randomPlantDefense()}
function randomPlantDefense(){const lanes=[0,1,2,3,4].sort(()=>Math.random()-.5);addPlant('sunflower',0,pick(lanes));addPlant('wallnut',2,pick(lanes));addPlant('peashooter',1,pick(lanes));if(state.level>=2&&Math.random()<.75)addPlant('peashooter',3,pick(lanes));if(state.level>=2&&Math.random()<.5)addPlant('potato',3,pick(lanes));if(state.level>=3)addPlant('wallnut',1,pick(lanes));if(state.level>=4)addPlant('firepea',3,pick(lanes));if(state.level>=5)addPlant('peashooter',4,pick(lanes));if(state.level>=6)addPlant('zhaoyun',4,pick(lanes));if(state.level>=7)addPlant('zhangfei',2,pick(lanes));if(state.level>=8)addPlant('huangzhong',5,pick(lanes));if(state.level>=9)addPlant('wallnut',3,pick(lanes));log(`${state.levelConfig.name}電腦三國守方建立${levelPhase()}防線。`)}
function buildGrid(){$('grid').innerHTML='';for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++){const cell=document.createElement('div');cell.className='cell';cell.dataset.r=r;cell.dataset.c=c;if(c===0){const lab=document.createElement('div');lab.className='lane-label';lab.textContent=`第 ${r+1} 路`;cell.appendChild(lab)}cell.onclick=()=>place(r,c);cell.ondragover=e=>{e.preventDefault();cell.classList.add('drop-preview')};cell.ondragleave=()=>cell.classList.remove('drop-preview');cell.ondrop=e=>{e.preventDefault();cell.classList.remove('drop-preview');const key=e.dataTransfer.getData('text/plain')||state.selected;deploySelected(key,r,c)};$('grid').appendChild(cell)}}
function buildCards(){const defs=state.faction==='plants'?PLANT_TYPES:ZOMBIE_TYPES,isCoarse=matchMedia('(pointer:coarse)').matches;$('cards').innerHTML='';const generalKeys=['firepea','zhangfei','zhaoyun','machao','huangzhong','kongming','pangtong','liubei','football','jester','bombJester','corpseTitan','fireCatapult','qinEmperor','necromancer'];sortUnits(Object.entries(defs).filter(([key,d])=>!d.hidden&&canUseUnit(state.faction,key,state.level)),state.faction).forEach(([key,d])=>{const b=document.createElement('button');b.className='card type-'+key+(generalKeys.includes(key)?' general':'');b.dataset.key=key;b.draggable=!isCoarse;const icon=d.asset?`<img class="char-img card-img" src="${d.asset}" alt="${d.name}">`:`<div class="emoji">${d.emoji}</div>`;b.innerHTML=`${icon}<div class="name">${d.name}</div><div class="cost">${d.cost} ${state.faction==='plants'?'軍糧':'腦'}</div><div class="statusline">冷卻 ${Math.round(d.cooldown/1000)} 秒</div><div class="card-desc">${CHARACTER_EXTRAS[key]||d.desc}</div><div class="coolbar"><div class="coolfill"></div></div>`;b.onclick=()=>selectCard(key);if(!isCoarse){b.ondragstart=e=>{selectCard(key);b.classList.add('dragging');e.dataTransfer.setData('text/plain',key);e.dataTransfer.effectAllowed='copy'};b.ondragend=()=>b.classList.remove('dragging')}$('cards').appendChild(b)})}
function isCooling(key){const d=effectiveUnit(state.faction,key);return state.time-(state.lastHuman[key]??-999999)<d.cooldown}
function selectCard(key){sfx('click');const defs=state.faction==='plants'?PLANT_TYPES:ZOMBIE_TYPES,d=effectiveUnit(state.faction,key);if(state.resource<d.cost){log(`${d.name} 資源不足。`);return}if(isCooling(key)){log(`${d.name} 還在冷卻。`);return}state.actionMode=null;state.movingPlantId=null;updateBattleActionUI();state.selected=key;document.querySelectorAll('.card').forEach(x=>x.classList.toggle('selected',x.dataset.key===key))}
const CHARACTER_EXTRAS={peashooter:'蜀軍基礎遠程兵，穩定射箭壓制同一路敵人，是前期守線主力。',sunflower:'軍糧官負責補充軍糧，越早部署越能撐起後續武將與防線。',wallnut:'厚盾守將，站在前排吸收傷害，替後方弓兵與武將爭取輸出時間。',firepea:'關羽的天賦讓所有攻擊固定帶火焰；機率技能發動時造成更強的青龍爆擊。',potato:'潛伏在格內的伏兵，需要時間準備；敵人靠近後爆發突襲，適合守關鍵路線。',zhangfei:'張飛的天賦讓每次近戰攻擊固定彈開敵人；機率技能發動時追加更強的震軍爆擊。',zhaoyun:'趙雲的天賦讓所有遠程攻擊固定附帶寒冰緩速；機率技能發動時追加冰龍爆擊。',machao:'馬超的天賦讓每次攻擊固定穿刺前方三格內最多三名敵人；機率技能發動時追加鐵騎爆擊。',huangzhong:'黃忠的天賦讓每次攻擊固定涵蓋上、中、下三列；機率技能發動時三列箭矢都造成百箭爆擊。',kongming:'軍神孔明以八陣圖引動全場雷陣，造成全地圖一次性高輸出，施放後退場。',pangtong:'火神龐統燃起三列鳳火，對自身列與上下列造成爆發傷害，屬於一次性戰術王牌。',liubei:'劉備固定召喚蜀軍鄉勇補線；機率技能發動時，改為召喚上、中、下三路白毦禁衛。',normal:'赤巾小屍是最便宜的進攻單位，速度普通、壓線穩定，適合用來消耗推車與探路。',cone:'鐵盔小兵防禦較高，能替後方單位吸收火力，是突破防線的基本肉盾。',bucket:'巨槌阿蠻體型厚重、血量高，移動較慢但很耐打，適合壓在主攻路線最前方。',football:'白髮屍王速度快、傷害高，是後期突破核心，適合搭配肉盾後突然壓線。',peaZombie:'飛石阿投可從遠處反覆投石，削弱守方前排，逼迫三國方分心處理。',poleVault:'蹦蹦飛屍開場高速衝刺，能跳過第一名守方角色，落地後變回一般速度繼續推進。',jester:'鈴鐺丑屍是將軍級混亂術師，綠髮、鈴鐺尖帽與骷髏權杖讓人一眼認出屍潮中的怪笑指揮官。能力「亂陣狂笑」會震懾同一路守方，造成傷害並讓守方短暫混亂停手，適合在防線密集時撕開破口。',bombJester:'爆爆桶屍是將軍級爆破狂徒，背滿炸藥、火藥桶與燃燒導火線，衝進防線就準備把自己變成最後煙火。能力「終幕爆彈」會在被打敗時自爆，對自身周圍九宮格內的守方造成重創；適合逼三國守方分散站位，避免整排防線被一口氣炸開。',corpseTitan:'屍旗大胖是將軍級攻城巨屍，背負「屍」字戰旗，肩上屍兵敲鼓催戰，以巨大拳頭正面碾開防線。能力「破城屍槌」會重擊前方守方，並震傷目標周圍九宮格內的守方、短暫打斷行動；適合當屍潮最後壓線的主將。',fireCatapult:'烈焰屍車是將軍級攻城兵器，木製戰車綁滿鐵刺、骷髏旗與紅色戰布，車上僵屍操縱燃燒巨石轟向城牆。能力「烈焰轟石」會遠距離鎖定同一路防線最密集處，砸下火焰巨石並對目標周圍九宮格造成濺射傷害，是專門拆陣的攻城後排。',qinEmperor:'始皇屍帝自古墓中率兵馬俑復甦，黑金冕旒與幽綠召令象徵跨越千年的不死帝權。天賦會召出秦俑屍兵持續推進；機率技能則號令上、中、下三路玄甲禁軍一同壓境。',necromancer:'冥火屍巫是屍潮終局的紫焰咒術師，手持骷髏法杖，以符咒與幽魂火焰封鎖整條戰線。天賦「幽冥禁咒」能從遠處傷害同一路守方，並讓目標短暫混亂停手。'};
function fmtVal(v,unit=''){return v===undefined||v===null?'—':`${Math.round(v*100)/100}${unit}`}
function statAttack(d){if(d.produce)return `補給 +${d.produce}`;if(d.oneUse)return fmtVal(d.damage);if(d.catapult)return `${d.catapultDamage}（濺射 ${Math.round(d.catapultDamage*d.catapultSplash)}）`;if(d.siegeSmash)return `${d.damage} / 技能 ${d.smashDamage}`;if(d.bombDeath)return `${d.damage} / 自爆 ${d.bombDamage}`;if(d.laugh)return `${d.damage} / 狂笑 ${d.laughDamage}`;if(d.curse)return `${d.damage} / 禁咒 ${d.curseDamage}`;return fmtVal(d.damage||d.meleeDamage||0)}
function statMeleeAttack(d,roster){if(d.meleeDamage)return fmtVal(d.meleeDamage);if(roster==='zombies'&&!d.shoot&&!d.catapult)return fmtVal(d.damage||0);if(d.siegeSmash)return `${d.damage}（普攻）`;if(d.bombDeath||d.laugh)return fmtVal(d.damage||0);if(d.range&&d.range<=1.2&&d.damage)return fmtVal(d.damage);return '—'}
function statRangedAttack(d,roster){if(d.produce)return `補給 +${d.produce}`;if(d.oneUse)return `${d.damage}（技能）`;if(d.catapult)return `${d.catapultDamage}（濺射 ${Math.round(d.catapultDamage*d.catapultSplash)}）`;if(d.shoot)return fmtVal(d.damage);if(d.tripleShot)return `${d.damage} × 三排`;if(d.pierce)return `${d.damage}（穿刺）`;if(d.slow&&d.damage)return fmtVal(d.damage);if(d.range&&d.range>1.2&&d.damage)return fmtVal(d.damage);if(d.bombDeath)return `${d.bombDamage}（自爆）`;if(d.laugh)return `${d.laughDamage}（狂笑）`;if(d.curse)return `${d.curseDamage}（冥火禁咒）`;if(d.siegeSmash)return `${d.smashDamage}（九宮格）`;return '—'}
function statDefense(d){return fmtVal(d.hp,' HP')}
function statRange(d,roster){if(d.oneUse==='global')return '全地圖';if(d.oneUse==='row')return '自身列＋上下列';if(d.tripleShot)return '三排遠程';if(d.catapult)return `同一路 ${d.catapultRange} 格＋九宮格`;if(d.siegeSmash||d.bombDeath)return '九宮格';if(d.pierce)return '前方三格穿刺';if(d.slow)return '同一路遠程＋近戰';if(d.shoot)return '同一路遠程投石';if(d.curse)return `同一路 ${d.curseRange} 格冥火`;if(d.summonRate)return '上/前/下三路召兵';if(d.range)return d.range>=8?'同一路全線':`${d.range} 格`;return roster==='plants'?'自身格/近戰':'近戰'}
function statMove(d,roster){if(roster==='plants')return d.speed?'可前進':'固定防守';if(d.canJump)return `開場快跑 ${d.speed}，跳後 ${d.spentSpeed}`;return d.speed?`${d.speed} / tick`:'固定'}
function statRate(d){if(d.produce)return `${Math.round(d.rate/1000)} 秒補給`;if(d.summonRate)return `${Math.round(d.summonRate/100)/10} 秒召喚｜機率強化`;if(d.catapultRate)return `${Math.round(d.catapultRate/1000)} 秒投石`;if(d.laughRate)return `${Math.round(d.laughRate/1000)} 秒狂笑`;if(d.curseRate)return `${Math.round(d.curseRate/100)/10} 秒施咒`;if(d.smashRate)return `${Math.round(d.smashRate/1000)} 秒重槌`;if(d.rate)return `${Math.round(d.rate/100)/10} 秒/次`;if(d.shoot)return '約 1.2 秒/次';return d.cooldown?`冷卻 ${Math.round(d.cooldown/1000)} 秒`:'—'}
function skillName(key,d){const map={sunflower:'軍糧補給',potato:'伏兵突襲',firepea:'青龍火斬',zhaoyun:'寒冰緩速',pangtong:'三列鳳火',machao:'三格穿刺',huangzhong:'百箭三排',kongming:'八陣雷擊',zhangfei:'近戰反推',liubei:'仁德召兵',poleVault:'竹竿跳越',peaZombie:'遠程投石',jester:'亂陣狂笑',bombJester:'終幕爆彈',corpseTitan:'破城屍槌',fireCatapult:'烈焰轟石',qinEmperor:'兵馬俑召令',necromancer:'幽冥禁咒'};return map[key]||d.desc||'基礎攻擊'}
const RELOCATABLE_GENERALS={zhaoyun:{cost:40,cooldown:8000},machao:{cost:40,cooldown:8000}};
function relocationDetail(key){const rule=RELOCATABLE_GENERALS[key];return rule?`騎兵調動：可調動到同欄相鄰一路，每次消耗 ${rule.cost} 軍糧；部署或上次調動後冷卻 ${Math.round(rule.cooldown/1000)} 秒。`:''}
function characterAbilityCardSummary(key,d,roster){const info=GENERAL_TALENTS[key];if(info){const level=charLevel(roster,key),chance=Math.round(superSkillChance(key,level)*100);return `<div class="ability-summary super-skill-summary"><b>天賦：${info.name}</b><span>${info.effect}</span><b>機率技能：${info.random}</b><span>Lv.${level} 發動率 ${chance}%｜每升一級 +2%，最高 60%</span></div>`}const talent=FIXED_TALENTS[key];if(talent)return `<div class="ability-summary fixed-talent-summary"><b>天賦：${talent.name}</b><span>${talent.effect}</span><span>影響範圍：${statRange(d,roster)}</span><span>攻擊/技能：${statAttack(d)}</span><small>固定生效</small></div>`;return `<div class="ability-summary basic-ability-summary"><b>招式：${skillName(key,d)}</b><span>影響範圍：${statRange(d,roster)}</span><span>生命 ${statDefense(d)}｜攻擊/技能 ${statAttack(d)}</span><span>施放節奏：${statRate(d)}</span><small>一般能力</small></div>`}
function skillDetail(key,d,roster){const area=statRange(d,roster),info=GENERAL_TALENTS[key];if(info){const level=charLevel(roster,key),chance=Math.round(superSkillChance(key,level)*100);return `天賦：${info.name}（固定生效）。${info.effect}機率技能：${info.random}。目前 Lv.${level} 發動率 ${chance}%；每升一級增加 2%，最高 60%。${info.bonus}影響範圍：${area}。${relocationDetail(key)}`}const talent=FIXED_TALENTS[key];if(talent)return `天賦：${talent.name}（固定生效）。${talent.effect}招式：${skillName(key,d)}。影響範圍：${area}。${d.oneUse?'一次性施放後退場。':''}`;let extra='';if(d.slow)extra='命中後會讓敵人緩速。';if(d.knockback)extra='近戰可把敵人反推出去。';if(d.oneUse)extra='一次性施放後退場。';if(d.bombDeath)extra='被打敗時才會觸發自爆。';if(d.laugh)extra='會讓同一路守方短暫混亂停手。';if(d.siegeSmash)extra='命中前方目標後震傷周圍九宮格。';if(d.catapult)extra='鎖定同一路最密集防線並造成火石濺射。';if(d.summonRate)extra='定時召喚上、前、下三路刀兵推進。';return `技能：${skillName(key,d)}。影響範圍：${area}。${extra}`}
function rangeCells(key,d,roster){const cells=[];for(let r=0;r<5;r++)for(let c=0;c<9;c++){let cls='range-cell';const origin=(r===2&&c===2);if(origin)cls+=' origin';let affect=false,support=false,lane=false;if(d.oneUse==='global')affect=true;else if(d.oneUse==='row')affect=Math.abs(r-2)<=1;else if(d.tripleShot)lane=Math.abs(r-2)<=1&&c>2;else if(d.catapult)affect=Math.abs(r-2)<=1&&Math.abs(c-5)<=1;else if(d.siegeSmash||d.bombDeath)affect=Math.abs(r-2)<=1&&Math.abs(c-3)<=1;else if(d.pierce)affect=r===2&&c>2&&c<=5;else if(d.summonRate)support=Math.abs(r-2)<=1&&c>=3&&c<=5;else if(d.slow||d.shoot||(d.range&&d.range>=8))lane=r===2&&c>2;else if(d.range)affect=r===2&&c>2&&c<=Math.min(8,2+Math.ceil(d.range));else affect=r===2&&c===3;if(affect)cls+=' affect';if(lane)cls+=' lane';if(support)cls+=' support';cells.push(`<div class="${cls}">${origin?'我':''}</div>`)}return cells.join('')}
function showCharacterDetail(roster,key){if(roster==='wei')return showWeiCharacterDetail(key);$('charModal').classList.remove('wei-preview');$('charModalSkillTitle').textContent='特殊技能 / 影響範圍';$('charModalStatsTitle').textContent='能力數值';const defs=roster==='plants'?PLANT_TYPES:ZOMBIE_TYPES,d=effectiveUnit(roster,key),base=defs[key];if(!d)return;$('charModalImg').src=base.guideAsset||base.asset||'';$('charModalImg').alt=d.name;$('charModalName').textContent=d.name;$('charModalRole').textContent=`${roster==='plants'?'蜀國':'僵屍方'}｜消耗 ${d.cost} ${roster==='plants'?'軍糧':'腦'}｜${skillName(key,d)}`;$('charModalIntro').textContent=CHARACTER_EXTRAS[key]||base.desc||'';$('charModalSkill').textContent=skillDetail(key,d,roster);$('charModalRange').innerHTML=rangeCells(key,d,roster);const stats=[['生命值 HP',statDefense(d)],['近戰攻擊力',statMeleeAttack(d,roster)],['遠戰/技能攻擊力',statRangedAttack(d,roster)],['防禦力',statDefense(d)],['攻擊範圍',statRange(d,roster)],['移動速度',statMove(d,roster)],['攻擊速度',statRate(d)],['卡片冷卻',fmtVal((d.cooldown||0)/1000,' 秒')],['下一級預覽',`HP ${effectiveUnit(roster,key,1).hp}｜遠戰/技能 ${statRangedAttack(effectiveUnit(roster,key,1),roster)}`]];if(RANDOM_SUPER_HEROES.has(key)){const level=charLevel(roster,key);stats.splice(3,0,['機率技能發動率',`${Math.round(superSkillChance(key,level)*100)}%（下級 ${Math.round(superSkillChance(key,level+1)*100)}%）`])}$('charModalStats').innerHTML=stats.map(([k,v])=>`<div class="stat-pill"><b>${k}</b><span>${v}</span></div>`).join('');$('charModal').classList.add('show');sfx('click')}
function closeCharacterDetail(){$('charModal').classList.remove('show')}
function avatarChoice(key=playerProfile.avatarKey){if(key==='custom'&&playerProfile.avatarUrl)return ['custom','自訂頭像',playerProfile.avatarUrl];return AVATAR_CHOICES.find(a=>a[0]===key)||AVATAR_CHOICES[0]}
function renderProfileAvatar(){const el=$('profileAvatar');if(!el)return;const a=avatarChoice(),img=document.createElement('img');try{const url=new URL(a[2],location.href);img.src=url.origin===location.origin||url.protocol==='https:'?url.href:AVATAR_CHOICES[0][2]}catch{img.src=AVATAR_CHOICES[0][2]}img.alt=`${a[1]}頭像`;el.replaceChildren(img)}
function renderAvatarPicker(){const grid=$('avatarGrid');if(!grid)return;grid.innerHTML=AVATAR_CHOICES.map(([key,name,src])=>`<button class="avatar-choice ${playerProfile.avatarKey===key?'active':''}" onclick="chooseAvatar('${key}')" aria-label="選擇${name}頭像"><img src="${src}" alt="${name}"><span>${name}</span></button>`).join('')}
function chooseAvatar(key){playerProfile.avatarKey=avatarChoice(key)[0];delete playerProfile.avatarUrl;saveProfile();renderProfileAvatar();renderAvatarPicker();refreshAccountCorner();sfx('click')}
function showProfileCenter(){playSceneMusic('stageSelect');['start','accountScreen','levelScreen','game','characters','shop'].forEach(id=>$(id)?.classList.remove('active'));$('profile').classList.add('active');$('playerNameInput').value=playerProfile.name||'訪客將軍';fillCloudForm();renderProfileAvatar();renderAvatarPicker();refreshProfileAuthBlocks();renderProfileStats();renderCharacterLevels(profileRoster);updateProfileRosterTabs()}
function renderProfileStats(){const progress=campaignStatus(),lock=playerProfile.syncLock||{},device=lock.deviceName?(isThisDevice(lock)?`這台裝置｜${lock.deviceName}`:`其他裝置｜${lock.deviceName}`):(currentUser?'尚未接管':'未登入');$('profileStats').innerHTML=[['玩家等級',`Lv.${playerProfile.level||1}`],['金幣',`🪙 ${playerProfile.gold||0}`],['經驗值',`⭐ ${playerProfile.xp||0}/${xpNeed()}`],['守城進度',`${progress.plants}/10`],['攻城進度',progress.attackUnlocked?`${progress.zombies}/10`:'守城第十關後解鎖'],['目前階段',progress.allComplete?'🏆 全破':'進行中'],['裝備/技能/服裝',`${Object.keys(playerProfile.inventory?.equipment||{}).length}/${Object.keys(playerProfile.inventory?.skills||{}).length}/${Object.keys(playerProfile.inventory?.skins||{}).length}`],['同步裝置',device],['存檔位置',currentUser?'本機＋帳號雲端':'本機 localStorage']].map(([k,v])=>`<div class="profile-stat"><b>${k}</b><span>${v}</span></div>`).join('')}
function updateProfileRosterTabs(){document.querySelectorAll('[data-profile-roster]').forEach(b=>b.classList.toggle('active',b.dataset.profileRoster===profileRoster))}
function renderCharacterLevels(roster='plants'){profileRoster=roster;const defs=roster==='plants'?PLANT_TYPES:ZOMBIE_TYPES;const grid=$('characterLevelGrid');if(!grid)return;grid.innerHTML=sortUnits(Object.entries(defs).filter(([k,d])=>!d.hidden),roster).map(([key,d])=>{const rec=playerProfile.characterLevels?.[roster]?.[key]||{level:1,xp:0};const need=characterXpNeed(rec.level),eff=effectiveUnit(roster,key),next=effectiveUnit(roster,key,1);const equipped=playerProfile.inventory?.equipped?.[roster]?.[key],eqName=equipped?SHOP_ITEMS.find(it=>it.key===equipped)?.name:'';return `<article class="char-level-card"><img src="${d.guideAsset||d.asset}" alt="${d.name}"><div><strong>${d.name}</strong><small>Lv.${rec.level}｜XP ${rec.xp}/${need}${eqName?`｜裝備：${eqName}`:''}</small><div class="mini-xpbar"><i style="width:${Math.min(100,rec.xp/need*100)}%"></i></div><div class="level-effects">HP ${eff.hp} → ${next.hp}｜攻 ${statRangedAttack(eff,roster)}｜下一級攻 ${statRangedAttack(next,roster)}</div><button class="secondary upgrade-btn" onclick="upgradeCharacter('${roster}','${key}')">${rec.xp>=need?'升級':'XP不足'}</button></div></article>`}).join('');updateProfileRosterTabs()}
function savePlayerName(){const name=($('playerNameInput').value||'').trim()||'訪客將軍';playerProfile.name=name;saveProfile();showProfileCenter();refreshAccountCorner();sfx('coin')}
async function resetLocalProfile(){if(!await showConfirm('重置本機存檔','金幣、經驗、通關、角色等級與商城收藏都會歸零。此操作無法復原。','確認重置',true))return;playerProfile=defaultProfile();saveProfile();showProfileCenter()}
function exportSavePayload(){return {game:SAVE_GAME_ID,version:SAVE_VERSION,savedAt:new Date().toISOString(),profile:normalizeProfile(playerProfile)}}
function setSaveStatus(msg){if($('saveStatus'))$('saveStatus').textContent=msg;if($('shopStatus'))$('shopStatus').textContent=msg}
function savePayloadText(){return JSON.stringify(exportSavePayload(),null,2)}
function encodeSaveCode(){return 'SGZ1-'+btoa(unescape(encodeURIComponent(JSON.stringify(exportSavePayload()))))}
function decodeSaveCode(code){const raw=(code||'').trim().replace(/^SGZ1-/,'');return JSON.parse(decodeURIComponent(escape(atob(raw))))}
function copySaveCode(){const code=encodeSaveCode();$('saveCodeBox').value=code;navigator.clipboard?.writeText(code).then(()=>setSaveStatus('存檔碼已複製。')).catch(()=>setSaveStatus('存檔碼已產生，請手動複製。'))}
function applyImportedProfile(payload){const data=payload?.profile?payload:{game:SAVE_GAME_ID,version:SAVE_VERSION,profile:payload};if(data.game&&data.game!==SAVE_GAME_ID)throw new Error('不是三國屍潮存檔');if(!data.profile)throw new Error('存檔缺少 profile');playerProfile=normalizeProfile(data.profile);saveProfile();showProfileCenter();setSaveStatus(`已匯入 ${playerProfile.name||'玩家'} 的存檔。`)}
function importSaveText(text){const trimmed=(text||'').trim();if(!trimmed)throw new Error('沒有存檔內容');const payload=trimmed.startsWith('SGZ1-')?decodeSaveCode(trimmed):JSON.parse(trimmed);applyImportedProfile(payload)}
function pasteSaveCode(){try{importSaveText($('saveCodeBox').value)}catch(e){setSaveStatus('存檔碼匯入失敗：'+e.message)}}
function showCharacters(roster='plants'){applyActiveSkins(roster);$('start').classList.remove('active');$('accountScreen')?.classList.remove('active');$('levelScreen').classList.remove('active');$('game').classList.remove('active');$('shop')?.classList.remove('active');$('characters').classList.add('active');buildCharacterGrid(roster);updateRosterTabs(roster)}
function updateRosterTabs(roster){document.querySelectorAll('[data-roster]').forEach(b=>{const active=b.dataset.roster===roster;b.classList.toggle('active',active);b.classList.toggle('primary',active);b.classList.toggle('secondary',!active);b.setAttribute('aria-pressed',String(active))})}
function isCharacterGuideUnlocked(roster,key){if(isFinalRewardUnit(roster,key))return isCampaignLevelCompleted('zombies',10);const level=UNLOCK_LEVEL[roster]?.[key]||1;return isCampaignLevelUnlocked(roster,level)}
function unlockLabel(roster,key,unlocked=isCharacterGuideUnlocked(roster,key)){if(isFinalRewardUnit(roster,key))return unlocked?'已解鎖｜攻城全破獎勵':'完成攻城第十關後解鎖';const lv=UNLOCK_LEVEL[roster]?.[key]||1;if(unlocked)return lv<=1?'已解鎖｜第一關起可用':`已解鎖｜第${levelLabel(lv)}關起可用`;return lv<=1?'第一關尚未解鎖':`通過第${levelLabel(lv-1)}關後解鎖`}
function buildCharacterGrid(roster='plants'){$('characters').classList.toggle('wei-guide',roster==='wei');$('characterRosterIntro').hidden=roster!=='wei';if(roster==='wei')return buildWeiCharacterGrid();const defs=roster==='plants'?PLANT_TYPES:ZOMBIE_TYPES;$('characterGrid').innerHTML='';sortUnits(Object.entries(defs).filter(([key,d])=>!d.hidden),roster).forEach(([key,d])=>{const card=document.createElement('article');const unlocked=isCharacterGuideUnlocked(roster,key);card.className='char-profile type-'+key+' '+((['zhangfei','zhaoyun','machao','huangzhong','kongming','pangtong','liubei','jester','bombJester','corpseTitan','fireCatapult','qinEmperor','necromancer'].includes(key))?'general':'')+' '+(unlocked?'':'locked');const resource=roster==='plants'?'軍糧':'腦';card.innerHTML=`<img src="${d.guideAsset||d.asset}" alt="${d.name}"><h3>${d.name}</h3><div class="costline">消耗 ${d.cost} ${resource}</div><div class="hp-line">HP 生命值：${effectiveUnit(roster,key).hp}</div><span class="unlock-badge">${unlockLabel(roster,key,unlocked)}</span><p>${CHARACTER_EXTRAS[key]||d.desc}</p>${characterAbilityCardSummary(key,effectiveUnit(roster,key),roster)}<div class="statusline">點擊查看技能範圍與能力數值</div>`;card.onclick=()=>showCharacterDetail(roster,key);$('characterGrid').appendChild(card)})}
function updateHUD(){updateProgressUI();const plant=state.faction==='plants',lv=state.levelConfig;$('resourceIcon').textContent=plant?'🌾':'🧠';$('resourceName').textContent=plant?'軍糧':'腦';$('resourceValue').textContent=Math.floor(state.resource);if($('aiIcon'))$('aiIcon').textContent=plant?'🧠':'🌾';if($('aiValue'))$('aiValue').textContent=Math.floor(state.aiResource);if($('aiName'))$('aiName').textContent=plant?'腦':'軍糧';$('modeTitle').textContent=`${lv.name}｜${plant?'三國守方防守':'僵屍進攻'}`;$('modeHint').textContent=plant?`${lv.plantHint}｜殭屍已出陣 ${state.enemiesSpawned}/${lv.enemyCount}${state.bossSpawned?'，大魔王已登場':'，全數派完後大魔王登場'}`:lv.zombieHint;$('objectiveTitle').textContent=`${lv.name}目標`;$('objectives').innerHTML=plant?`<li>用三國守方與推車守住 5 路戰線</li><li>開場準備時間較長，之後才逐步增加壓力</li><li>擊敗 ${lv.enemyCount} 名殭屍與最後的大魔王即可過關，不需等待固定秒數</li>`:`<li>突破${lv.shortName}防線與推車</li><li>吃掉守方角色直接 +50 腦</li><li>可等待腦力補給，${Math.round(lv.attackTimeLimit/1000)} 秒內突破即可</li>`;$('aiText').textContent=plant?`對方 ${Math.floor(state.aiResource)} 腦`:`對方 ${Math.floor(state.aiResource)} 軍糧`;$('aiMeter').style.width=Math.min(100,state.aiResource/(plant?Math.max(320,lv.plantAI+100):Math.max(280,lv.zombieAI+100))*100)+'%';document.querySelectorAll('.card').forEach(card=>{const d=effectiveUnit(state.faction,card.dataset.key),elapsed=state.time-(state.lastHuman[card.dataset.key]??-999999),cool=Math.max(0,d.cooldown-elapsed);card.classList.toggle('disabled',state.resource<d.cost||cool>0);card.querySelector('.coolfill').style.width=(cool>0?100-cool/d.cooldown*100:100)+'%'})}
function updateBattleActionUI(){if(!state)return;const defending=state.faction==='plants',remove=$('removeUnitBtn'),relocate=$('relocateUnitBtn');if(remove){remove.disabled=!defending;remove.classList.toggle('active',state.actionMode==='remove');remove.textContent=state.actionMode==='remove'?'取消移除':'🪏 移除武將'}if(relocate){relocate.disabled=!defending;relocate.classList.toggle('active',state.actionMode==='relocate');relocate.textContent=state.actionMode==='relocate'?'取消調動':'🐎 調動騎兵'}$('game')?.classList.toggle('remove-mode',state.actionMode==='remove');$('game')?.classList.toggle('relocate-mode',state.actionMode==='relocate')}
function setBattleActionMode(mode){if(!state||state.over||state.faction!=='plants')return;state.actionMode=state.actionMode===mode?null:mode;state.movingPlantId=null;state.selected=null;document.querySelectorAll('.card').forEach(x=>x.classList.remove('selected'));updateBattleActionUI();if(state.actionMode==='remove')log('移除模式：請點選要撤下的守方角色；撤下不退還軍糧。');if(state.actionMode==='relocate')log('調動模式：先選趙雲或馬超，再點同欄相鄰一路。')}
function plantAtCell(r,c){return state.plants.find(p=>p.r===r&&Math.abs(p.c-c)<.45)}
function removePlantAt(r,c){const plant=plantAtCell(r,c);if(!plant){log('這格沒有可移除的守方角色。');return false}state.plants=state.plants.filter(p=>p.id!==plant.id);state.actionMode=null;state.movingPlantId=null;log(`撤下 ${PLANT_TYPES[plant.type]?.name||'守方角色'}；本次不退還軍糧。`);updateBattleActionUI();render();return true}
function finishRelocation(message){state.actionMode=null;state.movingPlantId=null;updateBattleActionUI();if(message)log(message)}
function relocatePlantAt(r,c){const selected=state.plants.find(p=>p.id===state.movingPlantId);if(!selected){const plant=plantAtCell(r,c),rule=plant&&RELOCATABLE_GENERALS[plant.type];if(!plant){log('這格沒有可調動的騎兵。');return}if(!rule){finishRelocation('只有趙雲、馬超可以跨列調動。');return}const wait=rule.cooldown-(state.time-(plant.lastRelocatedAt??plant.bornAt??0));if(wait>0){finishRelocation(`${PLANT_TYPES[plant.type].name} 還要 ${Math.ceil(wait/1000)} 秒才能調動。`);return}if(state.resource<rule.cost){finishRelocation(`調動需要 ${rule.cost} 軍糧。`);return}state.movingPlantId=plant.id;log(`已選 ${PLANT_TYPES[plant.type].name}；請點同欄相鄰一路的空格。`);return}const rule=RELOCATABLE_GENERALS[selected.type];if(c!==Math.round(selected.c)||Math.abs(r-selected.r)!==1){finishRelocation('只能移到同欄的上一或下一路。');return}if(plantAtCell(r,c)){finishRelocation('目標格已有守方角色。');return}const wait=rule.cooldown-(state.time-(selected.lastRelocatedAt??selected.bornAt??0));if(wait>0||state.resource<rule.cost){finishRelocation(wait>0?`${PLANT_TYPES[selected.type].name} 尚在調動冷卻。`:`調動需要 ${rule.cost} 軍糧。`);return}state.resource-=rule.cost;selected.r=r;selected.c=c;selected.lastRelocatedAt=state.time;finishRelocation(`${PLANT_TYPES[selected.type].name} 換到第 ${r+1} 路（-${rule.cost} 軍糧）。`);sfx('place');updateHUD();render()}
function place(r,c){if(state.over)return;if(state.actionMode==='remove'){removePlantAt(r,c);return}if(state.actionMode==='relocate'){relocatePlantAt(r,c);return}if(!state.selected)return;deploySelected(state.selected,r,c)}
function deploySelected(key,r,c){if(state.over||!key)return;const defs=state.faction==='plants'?PLANT_TYPES:ZOMBIE_TYPES,d=defs[key];if(!d||!canUseUnit(state.faction,key,state.level))return;if(state.faction==='plants'){if(c>6){log('三國守方只能先部署在前 7 欄。');return}if(state.plants.some(p=>p.r===r&&p.c===c)){log('這格已有守方角色。');return}if(state.resource<d.cost){log(`${d.name} 資源不足。`);return}if(isCooling(key)){log(`${d.name} 還在冷卻。`);return}state.resource-=d.cost;state.lastHuman[key]=state.time;recordUsedCharacter('plants',key);addPlant(key,c,r);log(`部署 ${d.name}（-${d.cost} 軍糧）`);sfx(d.oneUse?'boom':'place')}else{if(c<7){log('僵屍要從右側兩欄出兵。');return}if(state.resource<d.cost){log(`${d.name} 資源不足。`);return}if(isCooling(key)){log(`${d.name} 還在冷卻。`);return}state.resource-=d.cost;state.lastHuman[key]=state.time;recordUsedCharacter('zombies',key);addZombie(key,c+.35,r);log(`派出 ${d.name}（-${d.cost} 腦）`);sfx('place')}state.selected=null;document.querySelectorAll('.card').forEach(x=>x.classList.remove('selected'));updateHUD();render()}
function addPlant(type,c,r){const d=activeUnit('plants',type);state.plants.push({id:crypto.randomUUID(),type,c,r,hp:d.hp,maxHp:d.hp,last:0,bornAt:state.time,lastRelocatedAt:state.time,armedAt:state.time+(d.armedAfter||0)})}
function addZombie(type,c,r){const d=activeUnit('zombies',type),zombie={id:crypto.randomUUID(),type,c,r,hp:d.hp,maxHp:d.hp,last:0,bornAt:state.time,jumped:false,shootLast:-999999};state.zombies.push(zombie);return zombie}
function spawnLevelBoss(){const lv=state.levelConfig,type=lv.bossType||'football',d=activeUnit('zombies',type),bossRow=Math.min(3,Math.max(1,smartZombieRow(type))),boss=addZombie(type,7.9,bossRow),hpScale=lv.bossHpMultiplier||2;boss.boss=true;boss.hp=Math.round(d.hp*hpScale);boss.maxHp=boss.hp;flash(boss,'👑 大魔王');sfx('ultimate');log(`⚠️ 關底大魔王「${d.name}」率領最後一波登場！`)}
function processLevelEvents(){if(state.faction!=='plants'||state.over)return;const lv=state.levelConfig;if(!state.bossSpawned&&state.enemiesSpawned>=lv.enemyCount&&state.time>=state.nextAI){state.bossSpawned=true;state.openingQueue=[];state.nextAI=Infinity;spawnLevelBoss();return}if(state.openingQueue.length&&state.enemiesSpawned<lv.enemyCount&&state.time>=state.nextOpeningZombie){const type=state.openingQueue.shift();spawnRandomZombie(type);state.enemiesSpawned++;state.nextOpeningZombie=state.time+(lv.openingSpacing||6500);log(`第 ${state.enemiesSpawned}/${lv.enemyCount} 名殭屍開始試探，派出 ${ZOMBIE_TYPES[type].name}。`)}}
function processLingeringEffects(){for(const z of state.zombies){if(!z.burnUntil||!z.burnNext||z.hp<=0)continue;while(z.burnNext<=state.time&&z.burnNext<=z.burnUntil){z.hp-=z.burnDamage||25;z.burnNext+=1000;flash(z,'鳳火灼燒');attackFx(z,'fire')}}}
function tick(){if(state.over||state.paused)return;state.time+=50;income();processLevelEvents();aiAct();actPlants();actZombies();processLingeringEffects();moveProjectiles();cleanup();checkEnd();render();updateHUD();if(!state.over&&state.time%1000===0)persistBattleState()}
function income(){if(state.time>state.nextIncome){const lv=state.levelConfig;if(state.faction==='plants'){const gain=lv.plantIncome,aiGain=lv.zombieAIIncome;state.resource+=gain;state.aiResource+=aiGain;log(`${lv.shortName}補給：你 +${gain}，電腦僵屍能量 +${aiGain}。`)}else{const brainGain=lv.zombieIncome,aiGain=lv.plantAIIncome;state.resource+=brainGain;state.aiResource+=aiGain;log(`僵屍腦力慢慢恢復：你 +${brainGain}，電腦三國守方能量 +${aiGain}。`)}state.nextIncome+=rand(lv.incomeMin,lv.incomeMax)}}
function affordable(defs,res){return Object.entries(defs).filter(([k,d])=>!d.hidden&&d.cost<=res&&state.time-(state.lastAI[k]??-999999)>=d.cooldown)}
const AI_DELAYS={zombies:{bucket:8500,peaZombie:10500,poleVault:16500,football:24000,jester:32000,bombJester:38000,corpseTitan:47000,fireCatapult:54000,qinEmperor:60000,necromancer:Infinity},plants:{firepea:14000,zhaoyun:16500,pangtong:19000,zhangfei:23000,machao:24000,huangzhong:25000,kongming:31000,liubei:36000}};
function aiDelay(defs,key){const side=defs===ZOMBIE_TYPES?'zombies':'plants';return (AI_DELAYS[side]&&AI_DELAYS[side][key])||0}
function affordableAI(defs,res){return affordable(defs,res).filter(([k])=>state.time>=aiDelay(defs,k))}
function rowLoad(kind,r){const list=kind==='plant'?state.plants:state.zombies;return list.filter(e=>e.r===r).length}
function smartZombieRow(key){const rows=[0,1,2,3,4].map(r=>{const plants=state.plants.filter(p=>p.r===r),zombies=state.zombies.filter(z=>z.r===r),front=plants.length?Math.max(...plants.map(p=>p.c)):-1,back=plants.length?Math.min(...plants.map(p=>p.c)):9,defenseHp=plants.reduce((s,p)=>s+(p.hp||0),0),threat=plants.reduce((s,p)=>s+(PLANT_TYPES[p.type]?.damage||0)+(PLANT_TYPES[p.type]?.oneUse?80:0)+(PLANT_TYPES[p.type]?.produce?18:0),0),crowd=zombies.length*45,mower=state.lawnmowers?.[r]?.used?35:0,emptyBonus=plants.length===0?95:0,thinBonus=plants.length===1?58:plants.length===2?24:0,breakableBonus=(plants.length<=2&&front<=4)?46:0;let score=emptyBonus+thinBonus+breakableBonus+mower+rand(0,55)-crowd-(defenseHp/28)-(threat*.35);if(['peaZombie','fireCatapult'].includes(key)&&plants.length>=2)score+=55;if(['football','poleVault'].includes(key)&&(plants.length<=2||front<=3))score+=50;if(['bucket','corpseTitan','jester','bombJester','qinEmperor'].includes(key)&&plants.length>=2)score+=28;if(key==='normal'&&plants.length===0)score+=35;if(state.time<18000)score+=rand(0,70);return {r,score,plants:plants.length}}).sort((a,b)=>b.score-a.score);const top=rows.slice(0,Math.min(3,rows.length));return pick(top).r}
function chooseZombieAI(opts){const phase=state.time<12000?'early':state.time<24000?'mid':'late';let pool=opts;if(phase==='early')pool=opts.filter(([k])=>['normal','cone'].includes(k));else if(phase==='mid')pool=opts.filter(([k])=>k!=='football');if(!pool.length)pool=opts;const plantsByRow=[0,1,2,3,4].map(r=>state.plants.filter(p=>p.r===r).length);const pressure=plantsByRow.some(n=>n>=2);let weighted=[];for(const item of pool){const k=item[0];let w=1;if(k==='normal')w+=phase==='early'?3:1;if(k==='cone')w+=2;if(k==='bucket')w+=phase==='late'?2:0;if(k==='peaZombie'&&pressure)w+=3;if(k==='poleVault'&&phase==='late')w+=2;if(k==='jester'&&phase==='late'&&pressure)w+=2;if(k==='bombJester'&&phase==='late'&&pressure)w+=1;if(k==='corpseTitan'&&phase==='late'&&pressure)w+=1;if(k==='fireCatapult'&&phase==='late'&&pressure)w+=1;if(k==='football')w+=phase==='late'?1:0;for(let i=0;i<w;i++)weighted.push(item)}return pick(weighted)}
function laneZombiePressure(r){const zs=state.zombies.filter(z=>z.r===r);const closest=zs.length?Math.min(...zs.map(z=>z.c)):9;return zs.length*55+(9-closest)*14}
function choosePlantAI(opts){const urgent=[0,1,2,3,4].map(r=>({r,score:laneZombiePressure(r)-rowLoad('plant',r)*18+rand(0,10)})).sort((a,b)=>b.score-a.score)[0];const hasSun=state.plants.some(p=>p.type==='sunflower');let pool=opts;if(state.time<14000)pool=opts.filter(([k])=>['sunflower','wallnut','peashooter','potato'].includes(k));else if(urgent.score>70)pool=opts.filter(([k])=>['wallnut','peashooter','firepea','zhaoyun','zhangfei','potato'].includes(k));if(!hasSun&&opts.some(([k])=>k==='sunflower')&&state.time<18000)pool=opts.filter(([k])=>k==='sunflower');if(!pool.length)pool=opts;const key=pick(pool.concat(pool.filter(([k])=>['wallnut','peashooter'].includes(k))));const [unit,d]=key;const maxCol=state.level>=2?6:5;let col=unit==='wallnut'||unit==='zhangfei'?Math.min(maxCol-1,Math.max(2,Math.floor((state.zombies.filter(z=>z.r===urgent.r).sort((a,b)=>a.c-b.c)[0]?.c||5)-1))):unit==='sunflower'?0:(unit==='potato'?Math.min(maxCol-1,Math.max(2,Math.floor((state.zombies.filter(z=>z.r===urgent.r).sort((a,b)=>a.c-b.c)[0]?.c||5)-1))):Math.min(maxCol-1,rand(1,4)|0));let r=urgent.r;for(let tries=0;tries<20&&state.plants.some(p=>p.r===r&&p.c===col);tries++){r=(r+1)%ROWS;if(tries>8)col=(col+1)%maxCol}if(state.plants.some(p=>p.r===r&&p.c===col))return null;return {key:unit,d,r,c:col}}
function aiZombieTag(){return state.time<aiDelay(ZOMBIE_TYPES,'football')?'（強兵延後登場）':`（${state.levelConfig.shortName}）`}
function aiPlantTag(){return state.time<14000?'（先鋪基本防線）':`（${state.levelConfig.shortName}防線）`}
function aiPace(side){const lv=state.levelConfig;if(side==='zombies'){const progress=Math.max(0,Math.min(1,state.enemiesSpawned/Math.max(1,lv.enemyCount))),curve=Math.pow(progress,1.1),earlyMin=Math.max(6800,lv.openingSpacing||6800),earlyMax=earlyMin+1700,lateMin=Math.max(4000,lv.minSpawnSpacing||4000),lateMax=lateMin+1300;return rand(earlyMin+(lateMin-earlyMin)*curve,earlyMax+(lateMax-earlyMax)*curve)}const early=state.time<15000,mid=state.time<32000;if(early)return rand(lv.zombieAIMax+1200,lv.zombieAIMax+2400);if(mid)return rand(lv.zombieAIMin+650,lv.zombieAIMax+1100);return rand(Math.max(1100,lv.zombieAIMin-150),Math.max(1600,lv.zombieAIMin+600))}
function aiAct(){if(state.faction==='plants'&&(state.bossSpawned||state.enemiesSpawned>=state.levelConfig.enemyCount))return;if(state.time<state.nextAI)return;const lv=state.levelConfig;if(state.faction==='plants'){let opts=affordableAI(ZOMBIE_TYPES,state.aiResource).filter(([k])=>lv.zombieWeights.includes(k));if(!opts.length&&lv.zombieWeights.includes('normal')&&state.time-(state.lastAI.normal??-999999)>=ZOMBIE_TYPES.normal.cooldown){state.aiResource=Math.max(state.aiResource,ZOMBIE_TYPES.normal.cost);opts=[['normal',ZOMBIE_TYPES.normal]]}if(opts.length){const [key,d]=chooseZombieAI(opts);state.aiResource=Math.max(0,state.aiResource-d.cost);state.lastAI[key]=state.time;spawnRandomZombie(key);state.enemiesSpawned++;log(`第 ${state.enemiesSpawned}/${lv.enemyCount} 名殭屍出陣：${d.name}${aiZombieTag()}。`);state.nextAI=state.time+aiPace('zombies')}else state.nextAI=state.time+Math.max(1000,lv.minSpawnSpacing||4000)}else{const opts=affordableAI(PLANT_TYPES,state.aiResource).filter(([k])=>isUnlocked('plants',k,state.level));const plan=opts.length?choosePlantAI(opts):null;if(plan){state.aiResource-=plan.d.cost;state.lastAI[plan.key]=state.time;addPlant(plan.key,plan.c,plan.r);log(`電腦判斷第 ${plan.r+1} 路後部署 ${plan.d.name}${aiPlantTag()}。`);state.nextAI=state.time+aiPace('plants')}else state.nextAI=state.time+rand(1600,2800)}}
function spawnRandomZombie(key){addZombie(key,8.8,smartZombieRow(key))}
function actPlants(){for(const p of [...state.plants]){const d=activeUnit('plants',p.type);if(!d)continue;if(p.stunUntil&&state.time<p.stunUntil){if(!p.stunMarked||state.time-p.stunMarked>900){p.stunMarked=state.time;flash(p,'混亂')}continue}if(d.oneUse&&!p.used){p.used=true;if(d.oneUse==='global'){markAttack(p);state.zombies.forEach(z=>{z.hp-=d.damage;if(z.hp>0)z.slowUntil=Math.max(z.slowUntil||0,state.time+4000);attackFx(z,'boom')});globalStrikeFx();flash(p,'八陣圖');attackFx(p,'boom');sfx('ultimate');log('軍神孔明發動全地圖八卦攻擊，使用後消失。')}else if(d.oneUse==='row'){markAttack(p);state.zombies.filter(z=>Math.abs(z.r-p.r)<=1).forEach(z=>{z.hp-=d.damage;if(z.hp>0){z.burnUntil=Math.max(z.burnUntil||0,state.time+3000);z.burnDamage=25;z.burnNext=state.time+1000}attackFx(z,'fire')});tripleFireFx(p.r);flash(p,'三列鳳火');attackFx(p,'fire');sfx('ultimate');log('火神龐統發動三列鳳火攻擊，使用後消失。')}p.expireAt=state.time+650;continue}if(p.type==='swordSoldier'||p.type==='whiteFeatherGuard'){const target=state.zombies.filter(z=>z.r===p.r&&z.c>p.c&&z.c-p.c<=d.range).sort((a,b)=>a.c-b.c)[0];if(target&&state.time-p.last>d.rate){markAttack(p);p.last=state.time;target.hp-=d.damage;flash(target,'刀');attackFx(target,'slash');sfx('hit')}else if(!target){p.c=Math.min(8.65,p.c+d.speed)}continue}if(p.type==='sunflower'&&state.time-p.last>d.rate){p.last=state.time;if(state.faction==='plants')state.resource+=d.produce;else state.aiResource+=d.produce;flash(p,'🌾')}if(p.type==='potato'&&state.time>p.armedAt){const z=state.zombies.find(z=>z.r===p.r&&Math.abs(z.c-p.c)<.42);if(z){markAttack(p);z.hp-=d.damage;p.hp=0;flash(p,'突襲');attackFx(z,'boom');sfx('boom');log('伏兵突襲成功！')}}if(d.tripleShot&&state.time-p.last>d.rate){const rows=[p.r-1,p.r,p.r+1].filter(r=>r>=0&&r<ROWS),available=rows.map(r=>({r,target:state.zombies.find(z=>z.r===r&&z.c>p.c&&z.c-p.c<=d.range)})).filter(x=>x.target);if(available.length){const superActive=rollSuperSkill(p.type),damage=superActive?superSkillDamage(d.damage):d.damage;markAttack(p);available.forEach(({r})=>state.projectiles.push({x:p.c+.72,y:r+.5,r,dir:1,damage,from:'plant'}));huangzhongArrowRainFx(p,rows);if(superActive)announceSuperSkill(p,d);else sfx('shoot');p.last=state.time}}else if(d.pierce&&state.time-p.last>d.rate){const targets=state.zombies.filter(z=>z.r===p.r&&z.c>p.c&&z.c-p.c<=d.range).sort((a,b)=>a.c-b.c).slice(0,3);if(targets.length){const superActive=rollSuperSkill(p.type),damage=superActive?superSkillDamage(d.damage):d.damage;markAttack(p);targets.forEach(z=>{z.hp-=damage;flash(z,superActive?'爆擊・穿刺':'穿刺');attackFx(z,superActive?'ice':'slash')});pierceFx(p,d.range);if(superActive){lanceDashFx(p,d.range);announceSuperSkill(p,d)}else sfx('hit');p.last=state.time}}else if(d.knockback&&state.time-p.last>d.rate){const target=state.zombies.filter(z=>z.r===p.r&&z.c>p.c&&z.c-p.c<=d.range).sort((a,b)=>a.c-b.c)[0];if(target){const superActive=rollSuperSkill(p.type);markAttack(p);target.hp-=superActive?superSkillDamage(d.damage):d.damage;target.c=Math.min(8.9,target.c+d.knockback);if(superActive){zhangfeiRoarFx(p,target);flash(target,'爆擊・彈開');announceSuperSkill(p,d)}else{flash(target,'彈開');attackFx(target,'slash');sfx('hit')}p.last=state.time}}else if((d.range&&(d.damage||d.summon))&&state.time-p.last>(d.summon?d.summonRate:d.rate)){const target=state.zombies.find(z=>z.r===p.r&&z.c>p.c&&z.c-p.c<=d.range);if(target){const superActive=rollSuperSkill(p.type);markAttack(p);p.last=state.time;if(p.type==='liubei'){if(superActive){summonEliteGuards(p);announceSuperSkill(p,d)}else summonMilitia(p)}else{const near=target.c-p.c<=1.2&&d.meleeDamage,baseDamage=near?d.meleeDamage:d.damage;state.projectiles.push({x:p.c+.72,y:p.r+.5,r:p.r,dir:1,damage:superActive?superSkillDamage(baseDamage):baseDamage,fire:!!d.fire,slow:!!d.slow,from:'plant'});if(superActive){if(p.type==='firepea')guanyuDragonSlashFx(p,target);if(p.type==='zhaoyun')zhaoyunIceDragonFx(p,target);announceSuperSkill(p,d)}else sfx('shoot')}}}}}
function catapultFireFx(center){for(let rr=center.r-1;rr<=center.r+1;rr++)for(let cc=center.c-1;cc<=center.c+1;cc++){if(rr<0||rr>=ROWS||cc<0||cc>=COLS)continue;const fx=document.createElement('div');fx.className='catapult-fire-fx';fx.style.left=`${(cc+.5)*CELL_W}%`;fx.style.top=`${(rr+.5)*CELL_H}%`;$('board').appendChild(fx);setTimeout(()=>fx.remove(),860)}}
function catapultFire(z,d){if(!d.catapult||state.time-(z.catapultLast||0)<d.catapultRate)return false;const candidates=state.plants.filter(p=>p.r===z.r&&p.c<z.c&&z.c-p.c<=d.catapultRange);if(!candidates.length)return false;const target=candidates.map(p=>({p,score:state.plants.filter(q=>Math.abs(q.r-p.r)<=1&&Math.abs(q.c-p.c)<=1).length*22+p.c+rand(0,6)})).sort((a,b)=>b.score-a.score)[0].p;markAttack(z);z.catapultLast=state.time;let hit=0;state.plants.forEach(p=>{if(Math.abs(p.r-target.r)<=1&&Math.abs(p.c-target.c)<=1){p.hp-=p.id===target.id?d.catapultDamage:d.catapultDamage*d.catapultSplash;hit++;flash(p,'烈焰轟石');attackFx(p,'fire')}});catapultFireFx({r:target.r,c:target.c});sfx('boom');log(`烈焰屍車發動「烈焰轟石」，九宮格火石濺射 ${hit} 名守方！`);return true}
function titanSmashFx(center){for(let rr=center.r-1;rr<=center.r+1;rr++)for(let cc=center.c-1;cc<=center.c+1;cc++){if(rr<0||rr>=ROWS||cc<0||cc>=COLS)continue;const fx=document.createElement('div');fx.className='titan-smash-fx';fx.style.left=`${(cc+.5)*CELL_W}%`;fx.style.top=`${(rr+.5)*CELL_H}%`;$('board').appendChild(fx);setTimeout(()=>fx.remove(),720)}}
function titanSiegeSmash(z,d,ahead){if(!d.siegeSmash||state.time-(z.smashLast||0)<d.smashRate)return false;markAttack(z);z.smashLast=state.time;const center={r:ahead.r,c:ahead.c};let hit=0;state.plants.forEach(p=>{if(Math.abs(p.r-center.r)<=1&&Math.abs(p.c-center.c)<=1){p.hp-=p.id===ahead.id?d.smashDamage:d.smashDamage*.55;p.stunUntil=Math.max(p.stunUntil||0,state.time+d.smashStun);flash(p,'破城震擊');attackFx(p,'boom');hit++}});titanSmashFx(center);sfx('boom');log(`屍旗大胖發動「破城屍槌」，九宮格震傷 ${hit} 名守方！`);return true}
function jesterLaugh(z,d){const targets=state.plants.filter(p=>p.r===z.r&&p.c<z.c&&z.c-p.c<=3.2);if(!targets.length||state.time-(z.laughLast||0)<d.laughRate)return false;markAttack(z);z.laughLast=state.time;targets.forEach(p=>{p.hp-=d.laughDamage;p.stunUntil=state.time+d.laughStun;flash(p,'狂笑混亂');attackFx(p,'laugh')});flash(z,'哈哈哈');sfx('ultimate');log('鈴鐺丑屍發動「亂陣狂笑」，同路守方短暫混亂停手！');return true}
function qinCommandFx(z,superActive=false){const fx=document.createElement('div');fx.className='qin-command-fx '+(superActive?'super':'ordinary');fx.textContent=superActive?'大秦軍陣':'兵馬俑召令';fx.style.left=`${(z.c+.5)*CELL_W}%`;fx.style.top=`${(z.r+.18)*CELL_H}%`;$('board').appendChild(fx);setTimeout(()=>fx.remove(),900)}
function summonQinArmy(z,d){const superActive=rollSuperSkill(z.type),rows=superActive?[z.r-1,z.r,z.r+1].filter(r=>r>=0&&r<ROWS):[z.r],type=superActive?'blackArmorGuard':'terracottaSoldier',spawnC=Math.min(8.55,z.c+.72);markAttack(z);z.last=state.time;z.summonLast=state.time;for(const r of rows){const unit=addZombie(type,spawnC,r);unit.summoned=true;unit.elite=!!ZOMBIE_TYPES[type].elite;flash(unit,superActive?'玄甲':'秦俑')}qinCommandFx(z,superActive);if(superActive)announceSuperSkill(z,d);else{sfx('ultimate');log(`${d.name} 發動「兵馬俑召令」，召出一名秦俑屍兵。`)}return true}
function necromancerCurseFx(z,target){const beam=document.createElement('div');beam.className='necromancer-curse-fx';beam.textContent='幽冥禁咒';beam.style.left=`${(target.c+.5)*CELL_W}%`;beam.style.top=`${(target.r+.5)*CELL_H}%`;beam.style.width=`${Math.max(1,(z.c-target.c))*CELL_W}%`;$('board').appendChild(beam);setTimeout(()=>beam.remove(),850)}
function necromancerCurse(z,d){if(!d.curse||state.time-(z.curseLast??-999999)<d.curseRate)return false;const target=state.plants.filter(p=>p.r===z.r&&p.c<z.c&&z.c-p.c<=d.curseRange).sort((a,b)=>b.c-a.c)[0];if(!target)return false;markAttack(z);z.curseLast=state.time;target.hp-=d.curseDamage;target.stunUntil=Math.max(target.stunUntil||0,state.time+d.curseStun);flash(target,'幽冥混亂');necromancerCurseFx(z,target);sfx('ultimate');log(`${d.name} 發動「幽冥禁咒」，紫焰使同路守方混亂停手！`);return true}
function actZombies(){for(const z of state.zombies){const d=activeUnit('zombies',z.type);if(d.curse&&necromancerCurse(z,d))continue;if(d.catapult&&catapultFire(z,d))continue;if(d.laugh&&jesterLaugh(z,d))continue;const jumpTarget=state.plants.filter(p=>p.r===z.r&&p.c<=z.c&&z.c-p.c<=.95).sort((a,b)=>b.c-a.c)[0];const ahead=state.plants.find(p=>p.r===z.r&&p.c<=z.c&&z.c-p.c<=d.range);if(d.shoot&&state.time-(z.shootLast??-999999)>1200){const target=state.plants.filter(p=>p.r===z.r&&p.c<z.c&&z.c-p.c<=4.8).sort((a,b)=>b.c-a.c)[0];if(target){markAttack(z);z.shootLast=state.time;state.projectiles.push({x:z.c-.35,y:z.r+.5,r:z.r,dir:-1,damage:d.damage,from:'zombie',rock:true,speed:.052,targetId:target.id});sfx('shoot');continue}}if(jumpTarget&&d.canJump&&!z.jumped){z.jumped=true;z.c=Math.max(.28,jumpTarget.c-.78);flash(jumpTarget,'🎋');log('蹦蹦飛屍跳過一名守方角色，速度變回赤巾小屍。');continue}if(ahead){if(d.summon&&state.time-(z.summonLast??-999999)>d.summonRate){summonQinArmy(z,d);continue}if(titanSiegeSmash(z,d,ahead))continue;if(state.time-z.last>(d.rate||700)){markAttack(z);z.last=state.time;ahead.hp-=d.damage;flash(ahead,'⚔️');attackFx(ahead,'slash');sfx('hit');if(ahead.hp<=0){if(state.faction==='zombies')state.resource+=50;else state.aiResource+=50;log(`${d.name} 吃掉守方角色，腦資源 +50。`)}}}else{z.c-=((z.jumped&&d.spentSpeed)?d.spentSpeed:d.speed)*(z.slowUntil&&state.time<z.slowUntil ? .45 : 1);if(z.c<=.25){triggerMower(z.r);if(z.hp<=0)continue}if(z.c<0)return end(state.faction==='zombies',state.faction==='zombies'?'突破成功！':'防線被突破！',state.faction==='zombies'?`${state.levelConfig.name}完成：僵屍突破推車後抵達左側。`:'推車已用完，僵屍突破庭院。')}}}
function triggerMower(r){const m=state.lawnmowers[r];if(!m||m.used||m.active)return;m.active=true;m.used=true;m.x=.3;state.zombies.filter(z=>z.r===r).forEach(z=>z.hp=0);log(`第 ${r+1} 路推車啟動，整排僵屍全清除！`);sfx('boom');let steps=0;const run=setInterval(()=>{if(!state||state.over){clearInterval(run);return}m.x+=.55;state.zombies.filter(z=>z.r===r).forEach(z=>z.hp=0);if(++steps>18){m.active=false;clearInterval(run)}},45)}
function moveProjectiles(){for(const pr of state.projectiles){pr.x+=pr.dir*(pr.speed||.085);if(pr.from==='plant'){const z=state.zombies.find(z=>z.r===pr.r&&Math.abs((z.c+.5)-pr.x)<.18);if(z){z.hp-=pr.damage;if(pr.slow)z.slowUntil=state.time+3200;pr.hit=true;flash(z,pr.slow?'❄️':(pr.fire?'🔥':'✹'));attackFx(z,pr.slow?'ice':(pr.fire?'fire':'slash'));sfx(pr.slow?'ice':(pr.fire?'fire':'hit'))}}else{const p=state.plants.find(p=>p.r===pr.r&&Math.abs((p.c+.5)-pr.x)<.18);if(p){p.hp-=pr.damage;pr.hit=true;flash(p,'✹');attackFx(p,'slash');sfx('hit')}}}}
function bombJesterBlastFx(z){for(let rr=z.r-1;rr<=z.r+1;rr++)for(let cc=Math.floor(z.c)-1;cc<=Math.floor(z.c)+1;cc++){if(rr<0||rr>=ROWS||cc<0||cc>=COLS)continue;const fx=document.createElement('div');fx.className='bomb-jester-blast';fx.style.left=`${(cc+.5)*CELL_W}%`;fx.style.top=`${(rr+.5)*CELL_H}%`;$('board').appendChild(fx);setTimeout(()=>fx.remove(),750)}}
function triggerBombJesterDeath(z){if(z.bombExploded)return;const d=ZOMBIE_TYPES[z.type];if(!d||!d.bombDeath)return;z.bombExploded=true;const centerC=Math.floor(z.c);let hit=0;state.plants.forEach(p=>{if(Math.abs(p.r-z.r)<=d.bombRadius&&Math.abs(p.c-centerC)<=d.bombRadius){p.hp-=d.bombDamage;hit++;flash(p,'爆破');attackFx(p,'boom')}});bombJesterBlastFx(z);flash(z,'終幕爆彈');sfx('boom');log(`爆爆桶屍被打敗後自爆，九宮格爆破命中 ${hit} 名守方！`)}
function cleanup(){state.zombies.filter(z=>z.hp<=0&&ZOMBIE_TYPES[z.type]?.bombDeath).forEach(triggerBombJesterDeath);state.plants=state.plants.filter(p=>p.hp>0||(p.expireAt&&state.time<p.expireAt));state.zombies=state.zombies.filter(z=>z.hp>0&&z.c>-0.2);state.projectiles=state.projectiles.filter(p=>!p.hit&&p.x>-1&&p.x<10)}
function checkEnd(){if(state.faction==='plants'){if(state.bossSpawned&&state.zombies.length===0)end(true,'防守成功！',`${state.levelConfig.name}完成：${state.levelConfig.enemyCount} 名殭屍與關底大魔王已全數擊敗。`)}else if(state.time>=state.levelConfig.attackTimeLimit){end(false,'進攻失敗',`進攻時間已到；本關可持續出兵 ${Math.round(state.levelConfig.attackTimeLimit/1000)} 秒。`)}}
function render(){const board=$('board');board.querySelectorAll('.entity,.projectile,.fx,.lawnmower').forEach(n=>n.remove());for(const m of state.lawnmowers)drawMower(m);for(const p of state.plants)drawEntity(p,'plant');for(const z of state.zombies)drawEntity(z,'zombie');for(const pr of state.projectiles){const el=document.createElement('div');el.className='projectile '+(pr.fire?'fire ':'')+(pr.slow?'ice ':'')+(pr.rock?'rock':'');if(pr.rock)el.textContent='🪨';el.style.left=`${pr.x*CELL_W}%`;el.style.top=`${pr.y*CELL_H}%`;board.appendChild(el)}}
function drawMower(m){const el=document.createElement('div');el.className='lawnmower '+(m.used&&!m.active?'used':'');el.textContent='🚜';el.style.left=`${m.x*CELL_W}%`;el.style.top=`${(m.r+.5)*CELL_H}%`;$('board').appendChild(el)}
function drawEntity(e,kind){const roster=kind==='plant'?'plants':'zombies',defs=kind==='plant'?PLANT_TYPES:ZOMBIE_TYPES,d=activeUnit(roster,e.type);const el=document.createElement('div');el.className=`entity ${kind} type-${e.type} ${e.boss?'boss ':''}${(state.time-(e.bornAt||0)<450)?'spawn':''} ${e.attackUntil&&state.time<e.attackUntil?'attacking':''} ${e.slowUntil&&state.time<e.slowUntil?'slowed ':''}${e.burnUntil&&state.time<e.burnUntil?'burning':''}`;el.style.left=`${(e.c+.5)*CELL_W}%`;el.style.top=`${(e.r+.5)*CELL_H}%`;const armed=e.type==='potato'&&state.time<e.armedAt?'未啟動':'';const spriteEmoji=e.type==='poleVault'&&e.jumped?(d.spentEmoji||'🧟'):d.emoji;const actionAsset=e.actionAssetUntil&&state.time<e.actionAssetUntil?e.actionAsset:null;const spriteAsset=actionAsset||(e.type==='poleVault'&&e.jumped?(d.spentAsset||d.asset):d.asset);const spriteHtml=spriteAsset?`<img class="char-img" src="${spriteAsset}" alt="${d.name}">`:spriteEmoji;const baseDisplay=e.type==='poleVault'&&e.jumped?'赤巾小屍':(armed||d.name),display=e.boss?`👑 大魔王・${baseDisplay}`:baseDisplay;el.innerHTML=`<div class="sprite">${spriteHtml}</div><div class="hpbar"><div class="hpfill" style="width:${Math.max(0,e.hp/e.maxHp*100)}%"></div></div><div class="label">${display}</div>`;$('board').appendChild(el)}
function flash(e,txt){const fx=document.createElement('div');fx.className='fx';fx.textContent=txt;fx.style.left=`${(e.c+.5)*CELL_W}%`;fx.style.top=`${(e.r+.25)*CELL_H}%`;$('board').appendChild(fx);setTimeout(()=>fx.remove(),650)}
async function end(win,title,text){
  if(state.over)return false;
  state.over=true;clearBattleSave();clearInterval(timer);
  const reward=addReward(win),usedKeys=Object.keys(state.usedUnits?.[state.faction]||{}),needsCloudVerification=!!(currentUser&&win);
  if(needsCloudVerification){
    $('modalTitle').textContent='⏳ 正在確認戰果';$('modalText').textContent='已完成本關，正在同步雲端進度，完成後即可進入下一關。';renderRewardPanel();
    if($('modalNext')){$('modalNext').textContent='同步戰果中…';$('modalNext').classList.remove('hidden');$('modalNext').disabled=true}
    if($('modalHome'))$('modalHome').classList.add('hidden');$('modal').classList.add('show');
  }
  const cloudVerified=currentUser?await claimCloudMatchReward(win,usedKeys):true;
  const step=cloudVerified?nextCampaignStep(state.faction,state.level,win):null,allComplete=win&&cloudVerified&&campaignStatus().allComplete;
  if(allComplete){title='🏆 目前階段全破';text='守城方第一至第十關與攻城方第一至第十關已全部完成；兩個陣營的已通關關卡都可自由重玩。'}
  else if(win&&!cloudVerified){title='戰果同步失敗';text='本場勝利尚未寫入雲端，請確認網路與裝置同步權限後重試本關，避免進度遺失。'}
  $('modalTitle').textContent=title;$('modalText').textContent=text;renderRewardPanel();
  if($('modalNext')){const allClearExit=win&&cloudVerified&&!step;$('modalNext').textContent=step?.label||(allClearExit?'全破完成｜回主選單':'目前階段全破');$('modalNext').classList.toggle('hidden',!step&&!allClearExit);$('modalNext').disabled=!step&&!allClearExit}
  const opposite=state.faction==='plants'?'zombies':'plants',switchBtn=$('modalHome');if(switchBtn){const canSwitch=cloudVerified&&isCampaignLevelUnlocked(opposite,state.level);switchBtn.disabled=!canSwitch;switchBtn.classList.toggle('hidden',!canSwitch)}
  $('modal').classList.add('show');log((win?'✅ ':'❌ ')+title+'｜'+reward);return cloudVerified
}
function advanceFromResult(){if(!state)return;const step=nextCampaignStep(state.faction,state.level,true);if(step&&isCampaignLevelUnlocked(step.faction,step.level)){selectedLevel=step.level;currentFaction=step.faction;$('modal')?.classList.remove('show');start(step.faction);return}backToHome()}
function goNextLevel(){return advanceFromResult()}
function togglePause(){if(!state||state.over)return;state.paused=!state.paused;applyPausedBattleUI();persistBattleState();log(state.paused?'遊戲暫停。':'遊戲繼續。');sfx('click')}
function syncFullscreenUI(){const on=document.fullscreenElement===$('game')||$('game')?.classList.contains('fullscreen-mode');$('game')?.classList.toggle('fullscreen-mode',on);if($('fullscreenBtn'))$('fullscreenBtn').textContent=on?'⛶ 離開全螢幕':'⛶ 全螢幕'}
async function toggleFullscreen(){const game=$('game');if(!game)return;sfx('click');try{if(document.fullscreenElement){await document.exitFullscreen()}else if(game.requestFullscreen){await game.requestFullscreen({navigationUI:'hide'})}else{game.classList.toggle('fullscreen-mode')}}catch(e){game.classList.toggle('fullscreen-mode');log('瀏覽器未允許原生全螢幕，改用頁面全螢幕版面。')}syncFullscreenUI();setTimeout(()=>{render();updateHUD()},80)}
function bind(id,fn){const el=$(id);if(el)el.onclick=fn}
function leaveFullscreenIfNeeded(){if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});$('game')?.classList.remove('fullscreen-mode');syncFullscreenUI()}
function backToHome(syncHistory=true){leaveFullscreenIfNeeded();pauseAndSaveBattle('navigation');clearInterval(timer);['accountScreen','levelScreen','game','characters','profile','shop'].forEach(id=>$(id)?.classList.remove('active'));$('game')?.classList.remove('level-2-night','paused');$('modal')?.classList.remove('show');$('start').classList.add('active');refreshResumeBattleUI();if(syncHistory)syncAppHistory('home','replace');playSceneMusic('main');refreshAccountCorner()}
function backToLevelSelect(syncHistory=true){leaveFullscreenIfNeeded();pauseAndSaveBattle('navigation');clearInterval(timer);$('game').classList.remove('active','level-2-night','paused');$('modal')?.classList.remove('show');$('levelScreen').classList.add('active');buildLevelCards();refreshResumeBattleUI();if(syncHistory)syncAppHistory('level','replace');playSceneMusic('stageSelect')}
function switchOppositeFactionSameLevel(){if(!state)return;const next=state.faction==='plants'?'zombies':'plants',level=state.level||selectedLevel;if(!isCampaignLevelUnlocked(next,level))return;clearInterval(timer);$('modal')?.classList.remove('show');selectedLevel=level;currentFaction=next;start(next)}
